#include <iostream>
#include <vector>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int E, M, D;
    if (!(cin >> E >> M >> D)) return 0;

    vector<pair<int, int>> same(M);
    for (int i = 0; i < M; ++i) {
        cin >> same[i].first >> same[i].second;
    }

    vector<pair<int, int>> diff(D);
    for (int i = 0; i < D; ++i) {
        cin >> diff[i].first >> diff[i].second;
    }

    vector<int> group_id(E + 1);
    int num_groups = E / 3;
    for (int g = 0; g < num_groups; ++g) {
        int u, v, w;
        cin >> u >> v >> w;
        group_id[u] = g;
        group_id[v] = g;
        group_id[w] = g;
    }

    int violations = 0;

    for (int i = 0; i < M; ++i) {
        if (group_id[same[i].first] != group_id[same[i].second]) {
            violations++;
        }
    }

    for (int i = 0; i < D; ++i) {
        if (group_id[diff[i].first] == group_id[diff[i].second]) {
            violations++;
        }
    }

    cout << violations << "\n";

    return 0;
}
